   365	// sameContents reports whether the files a and b in fs hold the same bytes.
   366	func sameContents(fs billy.Filesystem, a, b string) (same bool, err error) {
   367		fa, err := fs.Open(a)
   368		if err != nil {
   369			return false, err
   370		}
   371		defer ioutil.CheckClose(fa, &err)
   372		fb, err := fs.Open(b)
   373		if err != nil {
   374			return false, err
   375		}
   376		defer ioutil.CheckClose(fb, &err)
   377	
   378		bufA, bufB := make([]byte, 32*1024), make([]byte, 32*1024)
   379		for {
   380			na, errA := io.ReadFull(fa, bufA)
   381			nb, errB := io.ReadFull(fb, bufB)
   382			if na != nb || !bytes.Equal(bufA[:na], bufB[:nb]) {
   383				return false, nil
   384			}
   385			endA := errors.Is(errA, io.EOF) || errors.Is(errA, io.ErrUnexpectedEOF)
   386			endB := errors.Is(errB, io.EOF) || errors.Is(errB, io.ErrUnexpectedEOF)
   387			switch {
   388			case errA != nil && !endA:
   389				return false, errA
   390			case errB != nil && !endB:
   391				return false, errB
   392			case endA || endB:
   393				return endA == endB, nil
   394			}
   395		}
   396	}
